{
  "id": "PV-SENSE-001",
  "scope": "A linked evidence graph, not a matched longitudinal cohort. Each edge retains its assay and limits. Protein annotations, RNA expression, physiology and behavior are distinct evidence types.",
  "references": {
    "beeProtein": {"title":"Townson et al. (1998) · Honeybee blue/UV opsins and functional expression", "url":"https://doi.org/10.1523/JNEUROSCI.18-07-02412.1998"},
    "beeCurves": {"title":"Vasas et al. (2024) · Animal-view imaging and supporting curves", "url":"https://doi.org/10.1371/journal.pbio.3002444"},
    "beeData": {"title":"Vasas dataset · Figure S17A receptor curves · CC BY 4.0", "url":"https://doi.org/10.5281/zenodo.10145358"},
    "flyERG": {"title":"Sharkey et al. (2020) · Fly spectral sensitivity and eye filtering", "url":"https://doi.org/10.1038/s41598-020-74742-1"},
    "flyBehavior": {"title":"2023 · ON/OFF motion pathways and approaching color objects", "url":"https://doi.org/10.1038/s41467-023-43566-8"},
    "fishExpression": {"title":"Mitchell et al. (2021) · Retinal RNA and opsin co-expression", "url":"https://doi.org/10.1093/gbe/evab184"},
    "fishBehavior": {"title":"Mitchell et al. (2024) · UV vision and color discrimination", "url":"https://doi.org/10.1242/jeb.247425"},
    "fishData": {"title":"Clownfish spectra, optics and choice trials · Dryad · CC0", "url":"https://doi.org/10.5061/dryad.wwpzgmsp9"},
    "camera": {"title":"Burggraaff et al. (2019) · SPECTACLE consumer-camera calibration", "url":"https://doi.org/10.1364/OE.27.019075"}
  },
  "species": [
    {
      "id":"apis-mellifera", "name":"Honeybee", "scientific":"Apis mellifera", "niche":"Daylight insect · UV, blue and green pathways",
      "selection":"Reference receptor curves and functional opsin evidence provide a transparent spectral test case. No matched bee behavioral dataset is scored in this release.",
      "records":["AF004169.1","AF004168.1","U26026.1"],
      "chain":[
        {"label":"Sensory gene","title":"Three visual opsin reference records","evidence":"Deposited nucleotide sequences","text":"UV AMUVOP, blue AMBLOP and long-wavelength opsin records retain their annotated coding sequences. These records are not from the bees in the camera benchmark.","gap":"Genotype and expression are not jointly measured in the benchmark animals.","refs":["beeProtein"]},
        {"label":"Expressed protein","title":"Functional opsins, not an abundance map","evidence":"Heterologous functional assay + annotations","text":"Published blue and UV opsins were functionally expressed in Drosophila photoreceptors. Deposited translations identify the protein sequences; they do not quantify protein abundance in a honeybee eye.","gap":"No matched endogenous protein concentration or chromophore measurements.","refs":["beeProtein"]},
        {"label":"Sensory tissue","title":"Compound-eye photoreceptor pathways","evidence":"Published reference sensitivity curves","text":"The pilot uses the UV, blue and green curves provided with the animal-view imaging dataset. Eye geometry, retinal position, adaptation and neural processing are not modeled.","gap":"No independent ocular-filter ablation or regional expression measurements.","refs":["beeCurves","beeData"]},
        {"label":"Stimulus","title":"A laboratory spectrum probe","evidence":"Measured LED spectra, reused computationally","text":"76 clownfish-study LED targets probe the reference bee curves. The same held-out color families test every model. These are not recorded honeybee habitats.","gap":"Natural illumination and surface-reflectance generalization remain untested.","refs":["fishData"]},
        {"label":"Measured response","title":"Functional response linked; behavior unscored","evidence":"Published physiology / modeled pilot endpoint","text":"The molecular paper reports functional light responses. Here, phone-model outputs predict sensitivity-weighted scores only. No honeybee choices, neural recordings or subjective colors were measured for these targets.","gap":"A future bee behavior cohort is required for a complete stimulus-to-choice test.","refs":["beeProtein","beeData"]}
      ]
    },
    {
      "id":"drosophila-melanogaster", "name":"Fruit fly", "scientific":"Drosophila melanogaster", "niche":"Compound eye · opsins plus screening pigments",
      "selection":"Single-opsin rescue experiments expose why sequence or isolated pigment sensitivity alone can miss whole-eye filtering. The separate FlyBody specimen and neural-resource section now link this reference study to anatomical inspection; the source specimens are not experimentally matched.",
      "records":["P04950","P08255","P91657","P06002","O01668"],
      "chain":[
        {"label":"Sensory gene","title":"Rh3, Rh4, Rh5, ninaE/Rh1 and Rh6","evidence":"Reviewed UniProt protein references","text":"Five reference protein sequences are linked by gene name. Nucleotide sequences were not imported for the fly; the viewer does not fabricate an ATCG sequence from protein.","gap":"No allele-matched DNA, transcript and assay cohort.","refs":["flyERG"]},
        {"label":"Expressed protein","title":"Opsin-specific rescue provides functional evidence","evidence":"Genetic rescue + electrophysiology","text":"The source study isolates opsin contributions in rescue backgrounds. These engineered assays must remain distinct from normal whole-animal vision and quantitative pigment abundance.","gap":"Protein amounts and chromophore occupancy are not measured in this benchmark.","refs":["flyERG"]},
        {"label":"Sensory tissue","title":"Receptors act within an optically filtering eye","evidence":"Whole-eye physiological assay","text":"Rh1 is associated with outer R1–R6 cells; Rh3/Rh4 with R7 subtypes and Rh5/Rh6 with R8 subtypes. Screening and filtering pigments alter effective sensitivity. Only Rh3/Rh4/Rh5 short-range ERG means are used here.","gap":"This is not a full ommatidial, spatial, polarization or motion model.","refs":["flyERG"]},
        {"label":"Stimulus","title":"315–550 nm assay window","evidence":"Published mean ERG curves + computational LED probe","text":"The normalized mean ERG weights use the published short-range measurements. Longer Rh1/Rh6 series were not stitched to the short series because their overlapping amplitudes differ.","gap":"No inference beyond the assay window; ERG voltage is not a calibrated quantum-efficiency curve.","refs":["flyERG","fishData"]},
        {"label":"Measured response","title":"ERG physiology and a separate behavior study","evidence":"Measured ERG; behavior source linked, not reanalyzed","text":"The benchmark predicts ERG-weighted proxy scores. An independent study links spectral pathways to responses to approaching objects, but those trials are not included in these held-out results.","gap":"No demonstrated mapping from these phone scores to natural fly decisions.","refs":["flyERG","flyBehavior"]}
      ]
    },
    {
      "id":"amphiprion-ocellaris", "name":"Clown anemonefish", "scientific":"Amphiprion ocellaris", "niche":"Shallow reef fish · UV-transmitting optics",
      "selection":"Open retinal-expression evidence, lens measurements, spectral targets and individual choice trials support separate molecular and behavioral checks.",
      "records":["BK059178.1","BK059179.1","BK059182.1","BK059180.1","BK059181.1","BK059183.1","BK059184.1","BK059177.1"],
      "chain":[
        {"label":"Sensory gene","title":"An opsin repertoire with duplicated genes","evidence":"GenBank genomic reference records","text":"SWS1α/β, SWS2B, RH2A1/A2, RH2B, LWS and RH1 are linked to deposited coding sequences. Introns are preserved in the reference record; spliced CDS and annotated proteins are separately inspectable.","gap":"The references are not genotypes from the behavioral fish.","refs":["fishExpression"]},
        {"label":"Expressed protein","title":"RNA supports expression; protein abundance is unresolved","evidence":"RNA-seq + fluorescence in situ hybridization","text":"The 2021 retinal dataset detected six cone opsins and RH1, with co-expression in some cones. SWS1α was not detected in that dataset. RNA localization is not a measurement of protein concentration.","gap":"Do not treat an undetected transcript as universal gene absence, or one gene as one receptor class.","refs":["fishExpression"]},
        {"label":"Sensory tissue","title":"Cone pigment templates × measured lens transmission","evidence":"Physiology-fitted templates + lens measurements","text":"The pilot combines the published four cone templates with mean transmission from three lenses. Templates represent fitted pigment sensitivity, including the source's chromophore assumptions. Co-expression is not independently fitted here.","gap":"These optics and expression measurements come from different specimens/studies.","refs":["fishBehavior","fishData"]},
        {"label":"Stimulus","title":"76 measured LED targets in nine color families","evidence":"Published normalized spectral radiance","text":"Targets and a grey background were measured in the source experiment. Grey is excluded from scoring. Whole color families are held out, preventing intensity variants from appearing on both sides of a split.","gap":"Lab radiance is not reef illumination. Multiplying it by a habitat illuminant would double count the illumination.","refs":["fishData"]},
        {"label":"Measured response","title":"4,411 trial outcomes from 11 female fish","evidence":"Observed choice outcomes; secondary reanalysis","text":"There are 3,921 nonzero-contrast trials and 490 zero-contrast controls. One fish is held out at a time. Models compare training prevalence, published biological contrast (JND), and contrast plus the published UV-condition label. These are behavioral predictions, separate from the spectral phone benchmark.","gap":"Condition is confounded with color and experimental history. This is neither a causal UV test nor a sequence-only baseline.","refs":["fishBehavior","fishData"]}
      ]
    }
  ]
}

const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=n=>Number(n).toFixed(4);
const table=(caption,heads,rows)=>`<div class="table-wrap"><table><caption>${esc(caption)}</caption><thead><tr>${heads.map(x=>`<th scope="col">${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map((v,i)=>i?`<td>${esc(v)}</td>`:`<th scope="row">${esc(v)}</th>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const bars=(values)=>{const max=Math.max(...values.map(x=>x[1]));return values.map(([label,v])=>`<div class="score-row"><span>${esc(label)}</span><div class="track" aria-hidden="true"><div class="bar" style="width:${max?v/max*100:0}%"></div></div><strong>${number(v)}</strong></div>`).join('');};
let atlas,results,sequences,curves,species,step=0;
const sources=refs=>refs.map(id=>`<a href="${esc(atlas.references[id].url)}" target="_blank" rel="noopener">${esc(atlas.references[id].title)} ↗</a>`).join('');
function renderStep(){
  $('#chain').innerHTML=species.chain.map((n,i)=>`<button type="button" data-step="${i}" aria-pressed="${step===i}" aria-controls="evidence-detail"><span class="num">0${i+1}</span>${esc(n.label)}</button>`).join('');
  for(const button of document.querySelectorAll('[data-step]'))button.onclick=()=>{step=Number(button.dataset.step);renderStep();document.querySelector(`[data-step="${step}"]`).focus();};
  const n=species.chain[step];$('#evidence-detail').innerHTML=`<span class="evidence-type">${esc(n.evidence)}</span><h3>${esc(n.title)}</h3><p>${esc(n.text)}</p><p class="gap"><strong>Evidence gap:</strong> ${esc(n.gap)}</p><div class="refs">${sources(n.refs)}</div>`;
}
function renderSequence(){
  const r=sequences.records.find(r=>r.accession===$('#record').value),key=$('#sequence-view').value;
  $('#sequence-info').innerHTML=`<a href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.accession)} ↗</a> · ${esc(r.sourceMolecule)} · Protein ${esc(r.proteinAccession)}${r.cdsLocation?`<br>CDS: ${esc(r.cdsLocation)} (1-based, inclusive)`:''}<br><span class="small muted">${esc(r.translationCheck)}</span>`;
  const seq=r[key];$('#sequence-text').textContent=seq?seq.match(/.{1,60}/g).map((s,i)=>`${String(i*60+1).padStart(5)}  ${s}`).join('\n'):'Not imported. No nucleotide sequence is inferred from this protein.';
}
function renderCurves(channels){
  const key={'apis-mellifera':'bee','drosophila-melanogaster':'fly','amphiprion-ocellaris':'clownfish'}[species.id];
  const colors=['#d9a8ff','#70d8e7','#bce9ca','#f5c88c'];
  const paths=curves[key].map((a,j)=>{const max=Math.max(...a);return `<path d="${a.map((y,i)=>`${i?'L':'M'}${60+i*1.65},${220-y/max*180}`).join(' ')}" fill="none" stroke="${colors[j]}" stroke-width="2.5"/>`;});
  $('#curve-chart').innerHTML=`<svg viewBox="0 0 760 265" role="img" aria-label="Normalized spectral weights from 300 to 700 nanometers"><path d="M60 35V220H720" stroke="#6c898c" fill="none"/>${[300,400,500,600,700].map((w,i)=>`<text x="${60+i*165}" y="244" fill="#b6c9ca" font-size="13" text-anchor="middle">${w}</text>`).join('')}<text x="710" y="263" fill="#b6c9ca" font-size="12">nm</text><text x="28" y="45" fill="#b6c9ca" font-size="12">1</text><text x="28" y="220" fill="#b6c9ca" font-size="12">0</text>${paths.join('')}</svg><div class="legend">${channels.map((c,i)=>`<span style="--color:${colors[i]}">${esc(c)}</span>`).join('')}</div>`;
}
function renderScores(){
  const r=results.spectral.results.find(r=>r.species===species.id&&r.device===$('#device').value),m=r.models;
  $('#target-meaning').textContent=`${species.name}: ${r.targetMeaning}`;
  $('#scores').innerHTML=bars(Object.entries(m).map(([k,v])=>[k,v.macroMAE]));
  const d=r.uvMinusRgb;$('#interval').innerHTML=`<strong>Ideal UV minus RGB: ${number(d.estimate)} MAE</strong><p>Exploratory 95% bootstrap interval: ${number(d.lower)} to ${number(d.upper)}. Negative means lower error with ideal UV. ${d.upper>=0?'This interval crosses zero; an improvement is not resolved by this interval.':'This interval is below zero for these nine laboratory families.'}</p><p class="small">Not a 95% accuracy claim. Only nine family clusters; overlapping training sets and fixed calibration curves limit inference. This is not an interval for an animal’s perception.</p>`;
  const names=Object.keys(m);$('#fold-results').innerHTML=table('MAE by held-out color family',['Family',...names],m.RGB.folds.map((f,i)=>[f.family,...names.map(n=>number(m[n].folds[i].mae))]))+table('Pooled held-out error by channel',['Channel','RGB MAE','RGB RMSE','Ideal UV MAE'],r.channels.map((c,i)=>[c,number(m.RGB.maeByChannel[i]),number(m.RGB.rmseByChannel[i]),number(m['RGB + ideal UV'].maeByChannel[i])]))+table('Modeled RGB transfer without recalibration',['Training profile','Test profile','MAE'],results.spectral.transfer.filter(x=>x.species===species.id).map(x=>[x.trainDevice,x.testDevice,number(x.macroMAE)]))+'<p class="small muted">Transfer uses the same held-out families, but a different modeled sensor at test time. It is not a physical-device trial. Full per-family transfer scores and out-of-range prediction counts are in results.json.</p>';
  renderCurves(r.channels);
}
function chooseSpecies(id){
  species=atlas.species.find(s=>s.id===id)||atlas.species[0];step=0;
  for(const b of document.querySelectorAll('[data-species]'))b.setAttribute('aria-pressed',String(b.dataset.species===species.id));
  $('#species-summary').innerHTML=`<h3><i>${esc(species.scientific)}</i></h3><p class="muted">${esc(species.niche)}. ${esc(species.selection)}</p>`;
  $('#record').innerHTML=species.records.map(id=>{const r=sequences.records.find(r=>r.accession===id);return `<option value="${id}">${esc(id+' · '+r.gene)}</option>`;}).join('');
  $('#back-species').href='../../#'+species.id;
  $('#back-species').textContent='Return to the specimen archive ↗';
  if(species.id==='drosophila-melanogaster')$('#species-summary').insertAdjacentHTML('beforeend','<p><a href="../../#drosophila-melanogaster">Inspect the local FlyBody specimen ↗</a> · <a href="../../fruitfly-study-v0715.html">Explore source neurons and connectome resources ↗</a></p>');
  renderStep();renderSequence();renderScores();
}
async function boot(){
  [atlas,results,sequences,curves]=await Promise.all(['atlas','results','sequences','curves'].map(async n=>{const r=await fetch(`${n}.json`);if(!r.ok)throw Error(`${n}: ${r.status}`);return r.json();}));
  $('#species-buttons').innerHTML=atlas.species.map(s=>`<button data-species="${s.id}" aria-pressed="false">${esc(s.name)}</button>`).join('');
  for(const b of document.querySelectorAll('[data-species]'))b.onclick=()=>{history.replaceState(null,'','#'+b.dataset.species);chooseSpecies(b.dataset.species);};
  $('#device').onchange=renderScores;$('#record').onchange=renderSequence;$('#sequence-view').onchange=renderSequence;
  const behavior=results.behavior,models=behavior.models;
  $('#behavior-scores').innerHTML=table('All rows including controls · equal-fish average error · lower is better',['Model','Brier score','Log loss'],Object.entries(models).map(([k,v])=>[k,number(v.macroBrier),number(v.macroLogLoss)]))+`<details><summary>Nonzero-contrast trials only · post hoc diagnostic</summary><p class="small">${esc(behavior.nonzeroContrastDiagnostic.status)}</p>`+table('3,921 discrimination trials; excludes 490 zero-contrast controls',['Model','Brier score'],Object.entries(behavior.nonzeroContrastDiagnostic.models).map(([k,v])=>[k,number(v.macroBrier)]))+'</details>';
  const d=behavior.conditionMinusContrast;$('#behavior-finding').innerHTML=`<strong>Adding condition: ${number(d.estimate)} Brier score</strong><p>Exploratory paired 95% bootstrap interval: ${number(d.lower)} to ${number(d.upper)} across ${behavior.fishCount} fish. Overlapping training sets and the small cohort limit generalization.</p>`;
  const names=Object.keys(models);$('#fish-folds').innerHTML=table('Brier scores by held-out fish',['Fish','Choices',...names],models.Contrast.folds.map((f,i)=>[f.fish,f.testCount,...names.map(n=>number(models[n].folds[i].brier))]));
  $('#references').innerHTML=Object.values(atlas.references).map(r=>`<li><a href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.title)} ↗</a></li>`).join('');
  $('#failures').innerHTML=results.failures.map(s=>`<li>${esc(s)}</li>`).join('');
  $('#protocol-hash').textContent='Frozen protocol SHA-256: '+results.protocolSha256;
  chooseSpecies(location.hash.slice(1));$('#load-status').textContent='';
}
boot().catch(e=>{$('#load-status').textContent='Research data could not load. Reload this page or download the reproducible bundle. '+e.message;});

"""Numerical invariants, leakage boundaries and publication completeness."""
import hashlib,json,unittest
from pathlib import Path
import numpy as np
import analyze,prepare
BASE=Path(__file__).parent

class BenchmarkTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.data=json.loads((BASE/'inputs.json').read_text())
        cls.results=json.loads((BASE/'results.json').read_text())
        cls.pred=json.loads((BASE/'predictions.json').read_text())

    def test_sources_unchanged(self):
        for f in json.loads((BASE/'provenance.json').read_text())['files']:
            self.assertEqual(hashlib.sha256((BASE/f['path']).read_bytes()).hexdigest(),f['sha256'],f['path'])

    def test_frozen_protocol(self):
        self.assertEqual(hashlib.sha256((BASE/'protocol.json').read_bytes()).hexdigest(),'ecff2becd8f7c616fd05b4ff2e396000e9671cf003b48d2a97e9cb435d913837')

    def test_spectral_integration_identity_and_linearity(self):
        wl=np.arange(300.,701.);c=np.column_stack([wl,wl**2])
        a=np.ones((1,len(wl)))*.37
        np.testing.assert_allclose(prepare.weighted(a,c,wl),[[.37,.37]])
        np.testing.assert_allclose(prepare.weighted(a*2,c,wl),2*prepare.weighted(a,c,wl))
        with self.assertRaises(ValueError):prepare.weighted(a,np.zeros_like(c),wl)

    def test_ridge_training_scaling_and_intercept(self):
        x=np.array([[1.,3],[2,7],[4,2],[7,5]]);y=np.array([[.1],[.3],[.6],[.8]]);z=np.array([[10.,-9]])
        a=analyze.ridge_predict(x,y,z)
        # An extra test row cannot influence an existing prediction (no test-set scaling).
        np.testing.assert_allclose(a,analyze.ridge_predict(x,y,np.vstack([z,[1e9,1e9]]))[:1])
        np.testing.assert_allclose(a,analyze.ridge_predict(x*3+17,y,z*3+17))
        np.testing.assert_allclose(analyze.ridge_predict(x,np.ones((4,1))*.42,z),[[.42]])

    def test_logistic_training_only_and_probabilities(self):
        x=np.arange(10.)[:,None];y=np.array([0,0,0,0,1,0,1,1,1,1]);z=np.array([[-2.],[12.]])
        a=analyze.logistic_predict(x,y,z)
        self.assertTrue(np.all((a>0)&(a<1)));self.assertGreater(a[1],a[0])
        np.testing.assert_allclose(a,analyze.logistic_predict(x,y,np.vstack([z,[1e8]]))[:2])

    def test_all_spectral_folds_predict_each_target_once(self):
        d=self.data['spectral'];group=dict(zip(d['ids'],d['groups']))
        self.assertEqual(len(set(group.values())),9);self.assertEqual(len(group),76)
        for r in self.results['spectral']['results']:
            for model in r['models']:
                p=[p for p in self.pred['spectral'] if p['species']==r['species'] and p['device']==r['device'] and p['model']==model]
                self.assertEqual(sorted(p['id'] for p in p),sorted(group))
                self.assertTrue(all(p['heldOutFamily']==group[p['id']] for p in p))
                for fold in r['models'][model]['folds']:
                    self.assertEqual(fold['testCount'],list(group.values()).count(fold['family']))
                    self.assertEqual(fold['testCount']+fold['trainCount'],76)
                mae=np.mean([f['mae'] for f in r['models'][model]['folds']])
                self.assertAlmostEqual(mae,r['models'][model]['macroMAE'])

    def test_all_behavior_rows_held_out_by_fish(self):
        rows=self.data['behavior']['rows']
        self.assertEqual(len(rows),4411);self.assertEqual(len(set(r['fish'] for r in rows)),11)
        self.assertEqual(sum(r['jnd']==0 for r in rows),490)
        self.assertEqual(sum(r['success'] for r in rows if r['jnd']==0),0)
        for model in self.results['behavior']['models']:
            p=[p for p in self.pred['behavior'] if p['model']==model]
            self.assertEqual(sorted(x['row'] for x in p),list(range(len(rows))))
            self.assertTrue(all(x['fish']==rows[x['row']]['fish'] and x['observed']==rows[x['row']]['success'] for x in p))
            self.assertTrue(all(0<=x['probability']<=1 for x in p))

    def test_effect_intervals_do_not_claim_perceptual_accuracy(self):
        self.assertIsNone(self.results['primaryQuestion']['effect'])
        self.assertIsNone(self.results['primaryQuestion']['ci95'])
        self.assertIsNone(self.results['subjectiveVisionCI95'])
        self.assertFalse(self.results['livePhoneValidated'])
        fish=[f['brier'] for f in self.results['behavior']['models']['Contrast']['folds']]
        plus=[f['brier'] for f in self.results['behavior']['models']['Contrast + condition']['folds']]
        self.assertEqual(analyze.paired_interval(np.array(plus)-fish),self.results['behavior']['conditionMinusContrast'])

    def test_atlas_sources_records_and_molecule_types(self):
        atlas=json.loads((BASE/'atlas.json').read_text());seq=json.loads((BASE/'sequences.json').read_text())
        byid={r['accession']:r for r in seq['records']}
        self.assertEqual(len(byid),16)
        for s in atlas['species']:
            self.assertEqual(len(s['chain']),5)
            for r in s['records']:self.assertEqual(byid[r]['organism'],s['scientific'])
            for edge in s['chain']:
                self.assertTrue(edge['gap'])
                for ref in edge['refs']:self.assertIn(ref,atlas['references'])
        for r in seq['records']:
            self.assertEqual(hashlib.sha256(r['protein'].encode()).hexdigest(),r['proteinSha256'])
        self.assertIn('join(',byid['BK059178.1']['cdsLocation'])
        self.assertIsNone(byid['P04950']['dna'])

    def test_recomputed_scores_match_release(self):
        a=analyze.spectral_benchmark(self.data['spectral']);b=analyze.behavior_benchmark(self.data['behavior'])
        for expected,actual in zip(self.results['spectral']['results'],a['results']):
            for model in expected['models']:self.assertAlmostEqual(expected['models'][model]['macroMAE'],actual['models'][model]['macroMAE'],places=10)
        for model in b['models']:self.assertAlmostEqual(b['models'][model]['macroBrier'],self.results['behavior']['models'][model]['macroBrier'],places=10)

if __name__=='__main__':unittest.main()

